class _ExactOpenShopOrderEvaluator(BaseEvaluator):
    TASK_ID = ""
    EXPECTED: Mapping[str, Any] = {}
    RULESET_SPEC: Mapping[str, Any] = {}
    RULESET_SHA256 = ""
    CHECKPOINT_SPECS: list[Mapping[str, Any]] = []
    #: First additions the brief states as a sequence ("added in that exact sequence").
    ITEM_SEQUENCES: list[list[str]] = []
    #: The brief says "sign in ..., then" build the order.
    LOGIN_BEFORE_FIRST_ADD = False

    @staticmethod
    def _order_projection(order: Mapping[str, Any]) -> Mapping[str, Any]:
        projected_items = {}
        for raw_item in order.get("items") or []:
            item = dict(raw_item or {})
            product = dict(item.get("product") or {})
            review = item.get("review")
            projected_items[str(product.get("id") or "")] = {
                "title": str(product.get("title") or ""),
                "quantity": int(item.get("quantity") or 0),
                "selected_spec": str(item.get("selectedSpec") or ""),
                "rating": int((review or {}).get("rating") or 0) if review else None,
                "review": str((review or {}).get("review") or "") if review else None,
            }
        return {
            "id": str(order.get("id") or ""),
            "address": str((order.get("address") or {}).get("label") or ""),
            "payment": str((order.get("payment") or {}).get("label") or ""),
            "note": str(order.get("note") or ""),
            "status": str(order.get("status") or ""),
            "total": float(order.get("total") or 0),
            "items": projected_items,
        }

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        controller = context.get("controller")
        if controller is None or not hasattr(controller, "run_python_script"):
            return EvalResult(status=EvalStatus.ERROR, message="controller.run_python_script is required")
        params = dict(context.get("params") or {})
        port = int(params.get("port", 4310) or 4310)
        checks: list[dict[str, Any]] = []
        metadata: dict[str, Any] = {
            "task_id": self.TASK_ID,
            "ruleset_sha256": self.RULESET_SHA256,
            "ruleset_spec": dict(self.RULESET_SPEC),
            "checkpoint_specs": list(self.CHECKPOINT_SPECS),
            "source_state_mode": str(params.get("source_state_mode") or "fresh_clone_verified"),
            "read_only": True,
            "checks": checks,
        }

        def exact(
            check_id: str,
            value_contract_id: str,
            expected: Any,
            actual: Any,
            *,
            diagnostic: bool = False,
        ) -> None:
            passed = actual == expected
            record = {
                "check_id": check_id,
                "value_contract_id": value_contract_id,
                "match_mode": "SCALAR_EXACT" if not isinstance(expected, (dict, list)) else "ORDERED_EXACT",
                "expected": expected,
                "actual": actual,
                "passed": passed,
            }
            if diagnostic:
                record["diagnostic"] = True
            checks.append(record)
            if not passed and not diagnostic:
                raise AssertionError(f"{check_id}: expected {expected!r}, got {actual!r}")

        try:
            session_payload = OpenShopApiEvaluator._fetch_json(controller, "/api/session", port=port)
            cart_payload = OpenShopApiEvaluator._fetch_json(controller, "/api/cart", port=port)
            orders_payload = OpenShopApiEvaluator._fetch_json(controller, "/api/orders", port=port)
            benchmark_payload = OpenShopApiEvaluator._fetch_json(controller, "/api/benchmark", port=port)
            session = dict(session_payload.get("session") or {})
            orders = list(orders_payload.get("orders") or [])
            events = [dict(item or {}) for item in benchmark_payload.get("events") or []]
            metadata["raw_events"] = events
            if not orders:
                raise AssertionError("latest_order: no orders present")
            latest = self._order_projection(dict(orders[0] or {}))
            expected_order = dict(self.EXPECTED["order"])

            exact("session.logged_in", "session_login", True, bool(session.get("loggedIn")))
            exact("session.phone", "session_phone", "13800138000", str((session.get("user") or {}).get("phone") or ""))
            exact("cart.empty", "post_checkout_cart", 0, len(cart_payload.get("items") or []))
            for field in ("address", "payment", "note", "status", "total"):
                exact(f"latest_order.{field}", f"order_{field}", expected_order[field], latest[field])
            exact("latest_order.items", "order_items_exact", expected_order["items"], latest["items"])

            # Grade the business actions the brief asks for, not the recorded click
            # path: browsing, checkout clicks and cart-stepper events are never
            # required or counted (evaluators/windows/openshop_business_events.py).
            business = check_business_events(
                events,
                [("order", latest, expected_order)],
                item_sequences=self.ITEM_SEQUENCES,
                login_before_first_add=self.LOGIN_BEFORE_FIRST_ADD,
            )
            checks.extend(business)
            metadata["current_state_evidence"] = {
                "session": session,
                "cart_item_count": len(cart_payload.get("items") or []),
                "latest_order": latest,
                "raw_events": events,
                "benchmark_event_count": len(events),
            }
            failed = [row for row in business if not row["passed"]]
            if failed:
                raise AssertionError("; ".join(
                    f"{row['check_id']}: expected {row['expected']!r}, got {row['actual']!r}" for row in failed
                ))
        except AssertionError as exc:
            metadata["failure_reason"] = str(exc)
            return EvalResult(status=EvalStatus.FAIL, message=str(exc), metadata=metadata)
        except Exception as exc:
            metadata["failure_reason"] = f"{type(exc).__name__}: {exc}"
            return EvalResult(status=EvalStatus.ERROR, message=metadata["failure_reason"], metadata=metadata)

        return EvalResult(
            status=EvalStatus.PASS,
            message=f"{self.TASK_ID} exact OpenShop state and business events passed",
            metadata=metadata,
        )


def _project_items(items: Mapping[str, tuple[Any, ...]]) -> dict[str, Any]:
    return {
        product_id: {
            "title": title,
            "quantity": quantity,
            "selected_spec": spec,
            "rating": rating,
            "review": review,
        }
        for product_id, (title, quantity, spec, rating, review) in items.items()
    }


